p='lib/core/ui/components/cg_drill_card.dart'
s=open(p).read()
def rep(a,b):
    global s
    assert a in s, a
    s=s.replace(a,b)
# 1. meta fade
rep("""                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  _meta(c),""","""                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  // L'étiquette de verdict prend la place de la ligne rang · collège.
                  Opacity(opacity: 1 - _strongestPreview, child: _meta(c)),""")
rep("""  double _ramp(double distance)""","""  double get _strongestPreview => CgVerdict.values.map(_previewOpacity).reduce(math.max);

  double _ramp(double distance)""")
rep("""          targetAnchor: Alignment.bottomLeft,
          offset: const Offset(0, CgSpace.s2),""","""          targetAnchor: Alignment.bottomLeft,
          // Même hauteur que la ligne rang · collège (qu'elle remplace).
          offset: const Offset(0, CgSpace.s8),""")
# 2. answer fade
rep("""  bool _answerCanScroll = false;""","""  bool _answerCanScroll = false;

  /// Reste-t-il de la réponse sous le bord de la feuille ? (fondu en bas)
  bool _answerMoreBelow = false;""")
rep("""    return Listener(
      key: _cardKey,
      onPointerDown: (_) => _downOnAnswer = true,
      child: LayoutBuilder(builder: (context, area) {
        return SingleChildScrollView(""","""    final scroll = LayoutBuilder(builder: (context, area) {
        return SingleChildScrollView(""")
rep("""                style: CgType.body.copyWith(fontSize: _answerSize, color: c.ink),
              ),
            ),
          ),
        );
      }),
    );
  }""","""                style: CgType.body.copyWith(fontSize: _answerSize, color: c.ink),
              ),
            ),
          ),
        );
      });
    return Listener(
      key: _cardKey,
      onPointerDown: (_) => _downOnAnswer = true,
      child: NotificationListener<ScrollMetricsNotification>(
        onNotification: (n) => _onAnswerMetrics(n.metrics),
        child: NotificationListener<ScrollUpdateNotification>(
          onNotification: (n) => _onAnswerMetrics(n.metrics),
          child: ShaderMask(
            blendMode: BlendMode.dstIn,
            shaderCallback: (rect) => LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              stops: [1 - _answerFade / math.max(rect.height, _answerFade), 1],
              colors: [c.ink, c.ink.withValues(alpha: _answerMoreBelow ? 0 : 1)],
            ).createShader(rect),
            child: scroll,
          ),
        ),
      ),
    );
  }

  bool _onAnswerMetrics(ScrollMetrics m) {
    final more = m.extentAfter > 0;
    if (more != _answerMoreBelow && mounted) setState(() => _answerMoreBelow = more);
    return false;
  }""")
rep("""  /// Réponse 20/400 (interligne de `body`).
  static const _answerSize = 20.0;""","""  /// Réponse 20/400 (interligne de `body`).
  static const _answerSize = 20.0;

  /// Fondu du bas de la réponse quand elle défile (indice « il y a une suite »).
  static const _answerFade = CgSpace.s8;""")
open(p,'w').write(s)
